fn reverse(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n); // Create a new vector with the same capacity as the input

    for i in (0..n).rev() { // Iterate from n-1 down to 0
        a_rev.push(a[i]); // Push the elements in reverse order
    }

    a_rev // Return the reversed vector
}